'use strict';
const LiveActivityPanel = (() => {
 let current = null;
 let blobUrls = [];
 const expanded = new Set();
 const $ = id => document.getElementById(id);
 const labels = {waiting:'Waiting for context',queued:'Context ready · waiting for its turn',generating:'Generating response',validating:'Validating response',submitted:'Response submitted',stalled:'Stalled submission',interrupted:'Request interrupted',not_started:'Did not start'};
 const eventLabels = {batch_started:'Batch started',model_metadata:'Model verified',run_started:'Task run started',agent_observation:'Context recorded',generation_started:'Model request started',generation_result:'Model response received',task_update:'Answer submitted',communication_delivery:'Peer history delivered',communication_unlocked:'Communication unlocked',checkpoint_committed:'Checkpoint committed',minute_violation:'Deadline or submission violation',run_error:'Run error',run_finished:'Task run finished',batch_finished:'Batch finished',stop_requested:'Stop requested',researcher_action:'Researcher action'};
 function node(tag, className, text){const n=document.createElement(tag);if(className)n.className=className;if(text!==undefined)n.textContent=text;return n;}
 function duration(seconds){const s=Math.max(0,Math.floor(seconds));return `${Math.floor(s/60)}:${String(s%60).padStart(2,'0')}`;}
 function disclosure(key, className, title, text){const detail=node('details',className);detail.dataset.disclosureKey=key;detail.open=expanded.has(key);detail.append(node('summary','',title),node('pre','',text));detail.ontoggle=()=>{if(!detail.isConnected)return;if(detail.open)expanded.add(key);else expanded.delete(key);};return detail;}
 function responseCard(update){
  const card=node('article','live-response');const heading=node('div','live-response-heading',`Checkpoint ${update.step+1}`);heading.append(node('time','',new Date(update.timestamp).toLocaleTimeString()));card.append(heading,node('p','',update.response_text||`No answer generated: ${update.done_reason||'stalled'}`));
  const meta=[];if(update.agent_role==='feedback_only')meta.push('Feedback only · no goal submission');else if(update.answer_class!=null)meta.push(`Answer: ${update.answer_class}`);if(update.evaluator)meta.push(`Score: ${update.evaluator.score}`);meta.push(`${update.visible_message_ids?.length||0} peer updates delivered`);if(typeof update.latency_ms==='number')meta.push(`${(update.latency_ms/1000).toFixed(1)}s request`);card.append(node('p','live-response-meta',meta.join(' · ')));
  for(const insight of update.key_insights||[])card.append(node('p','live-insight',`Key insight: ${insight}`));
  if(update.candidate_key)card.append(node('p','live-response-meta',`B proposed key: ${update.candidate_key}`));
  if(update.evaluator?.unlock_status)card.append(node('p','live-goal-result',`Controller check: ${update.evaluator.unlock_status}${update.evaluator.final_answer_if_any?' · '+update.evaluator.final_answer_if_any.result:''}`));
  card.append(disclosure('source:'+update.event_id,'live-source','Source update',JSON.stringify(update,null,2)));return card;
 }
 function renderAgent(agent, record, runId){
  const host=$('live-agent-'+agent);host.replaceChildren();const status=node('div','agent-activity-state '+record.state);status.id='live-state-'+agent;status.textContent=labels[record.state]||record.state;host.append(status);
  if(record.observation){const availability=record.observation.communication_available;const role=record.observation.agent_role||'solver';host.append(node('p','live-response-meta',`${role==='feedback_only'?'Feedback only':role} · ${availability?'Peer channel open':'Isolated context'} · checkpoint ${record.observation.step+1}`));host.append(disclosure('context:'+runId+':'+agent,'live-context','Exact prepared context (submission is recorded separately)',JSON.stringify(record.observation.messages,null,2)));const p=record.observation.communication_projection;if(p)host.append(node('p','live-response-meta',`${p.delivered_bytes} projected peer bytes · ${p.omitted_message_ids.length} messages omitted · cost ${p.cost.toFixed(3)}`));}
  if(record.heartbeat_at)host.append(node('p','live-response-meta',`Controller heartbeat: ${new Date(record.heartbeat_at).toLocaleTimeString()}`));
  if(record.provider_cancellation_status==='unknown')host.append(node('p','live-response-meta','Provider cancellation unknown; controller attempt has ended.'));
  const transcript=node('div','live-transcript');for(const update of record.updates)transcript.append(responseCard(update));if(!record.updates.length)transcript.append(node('p','live-empty','No response submitted yet.'));host.append(transcript);
 }
 function render(data, live){const activity=data.live_activity;current={data,live};const header=$('live-header-summary');if(!activity){header.textContent=live?'Restart the panel to enable live activity.':'This older snapshot has no activity projection. Use Run inspector to browse its logs.';for(const id of ['download-completed-bundle','download-completed-responses'])$(id).hidden=true;return;}
  const run=activity.run;const executionLabel=activity.batch_status==='running'&&data.execution?.state!=='verified_worker'?'Recorded run · worker unverified':activity.batch_status.replaceAll('_',' ');header.textContent=run?`${executionLabel} · ${run.task?.title||run.task_id} · ${run.condition_id} · repeat ${(run.repeat??0)+1} · checkpoint ${activity.step==null?'pending':activity.step+1} · task status: ${run.status||'not recorded'}`:activity.batch_status==='running'?'Recorded batch · waiting for model metadata':'No task run selected.';
  const count=(data.events||[]).filter(e=>e.kind==='task_update').length;const expected=data.batch?.config?.expected_updates;const progress=$('live-progress');progress.max=expected||Math.max(count,1);progress.value=count;$('live-batch-progress').textContent=`${count}${expected?' / '+expected:''} batch updates recorded`;
  for(const agent of ['A','B'])renderAgent(agent,activity.agents[agent],run?.id||'pending');
  const shared=$('live-shared-history');shared.replaceChildren();const available=Object.values(activity.agents).some(a=>a.observation?.communication_available);shared.append(node('div','shared-state',available?'Peer channel open':'Peer channel closed'));
  for(const message of activity.shared_history){const card=node('article','live-response');card.append(node('strong','',`Agent ${message.agent_id} · checkpoint ${message.step+1}`),node('p','',message.response_text||'Stalled update'));for(const insight of message.key_insights||[])card.append(node('p','live-response-meta',`Recorded insight: ${insight}`));if(message.candidate_key)card.append(node('p','live-response-meta',`Recorded candidate key: ${message.candidate_key}`));card.append(node('small','',`Delivered to ${message.visible_to.join(', ')} · ${message.event_id}`));shared.append(card);}if(!activity.shared_history.length)shared.append(node('p','live-empty',available?'No previous peer updates delivered yet.':'Agents cannot see each other’s history here.'));
  const insightHost=$('live-key-insights');if(insightHost){insightHost.replaceChildren();for(const insight of activity.shared_key_insights||[]){const card=node('article','live-insight');card.append(node('strong','',insight.text),node('small','',`Agent ${insight.agent} · checkpoint ${insight.step+1} · delivered to ${insight.visible_to.join(', ')} · ${insight.source_event_id}`));insightHost.append(card);}if(!activity.shared_key_insights?.length)insightHost.append(node('p','live-empty',data.batch?.config?.shared_context_mode==='key_insights_plus_history'?'No highlighted peer insights delivered yet.':'Raw history mode · no separate highlighted section supplied to agents.'));}
  const feed=$('live-event-feed');feed.replaceChildren();for(const event of [...activity.feed].reverse()){const row=node('div','live-feed-row');row.append(node('time','',new Date(event.timestamp).toLocaleTimeString()),node('strong','',eventLabels[event.kind]||event.kind.replaceAll('_',' ')),node('span','',`${event.agent_id?'Agent '+event.agent_id:''}${event.step==null?'':' · checkpoint '+(event.step+1)}`));if(event.detail)row.append(node('span','',event.detail));row.title=event.event_id;feed.append(row);}
  for(const url of blobUrls)URL.revokeObjectURL(url);blobUrls=[];
  for(const [id,url] of [['download-completed-bundle',activity.exports.bundle_url],['download-completed-responses',activity.exports.responses_url]]){const link=$(id);link.hidden=!(activity.exports.available??activity.exports.ready);if(live&&url){link.href=url;link.removeAttribute('download');link.textContent=id==='download-completed-bundle'?`↓ Download ${activity.exports.partial?'partial ':''}batch logs · ZIP`:'↓ Responses · JSONL';}else if(activity.exports.ready){let text,name,type;if(id==='download-completed-bundle'){text=JSON.stringify(data,null,2);name='apart-research-snapshot.json';type='application/json';link.textContent='↓ Download batch snapshot · JSON';}else{const observations=new Map(data.events.filter(e=>e.kind==='agent_observation').map(e=>[e.event_id,e.payload]));text=data.events.filter(e=>e.kind==='task_update').map(e=>JSON.stringify({...e.payload,event_id:e.event_id,timestamp:e.timestamp,observation:observations.get(e.payload.observation_id)||null})).join('\n')+'\n';name='responses.jsonl';type='application/x-ndjson';}const blobUrl=URL.createObjectURL(new Blob([text],{type}));blobUrls.push(blobUrl);link.href=blobUrl;link.download=name;}else link.removeAttribute('href');}
  tick();
 }
 function tick(){
  if(!current?.data.live_activity)return;
  const {data}=current, activity=data.live_activity, now=Date.now();
  const verified=current.live&&data.execution?.state==='verified_worker', last=Date.parse(activity.last_event_at), config=data.batch?.config||{};
  for(const [id,startText,endText,budget,label] of [['live-run-clock',activity.run_started_at,activity.run_finished_at,config.deadline_seconds||300,'Task run'],['live-batch-clock',activity.batch_started_at,activity.batch_finished_at,config.batch_timeout_seconds||3600,'Whole batch']]){
   const host=$(id);if(!host)continue;const start=Date.parse(startText),end=Date.parse(endText),cutoff=Number.isFinite(end)?end:verified?now:last;
   host.textContent=Number.isFinite(start)&&Number.isFinite(cutoff)?`${label} ${duration((cutoff-start)/1000)} / ${duration(budget)} budget${Number.isFinite(end)?' · ended':verified?' · active':' · recorded span, worker unverified'}${(cutoff-start)/1000>budget?' · budget exceeded':''}`:'';
  }
  $('live-last-event').textContent=Number.isFinite(last)?`Last controller event ${Math.max(0,Math.floor((now-last)/1000))}s ago`:'';
  const summary=$('calibration-summary'), c=data.calibration;
  if(summary&&c)summary.textContent=`${c.valid_updates} valid · ${c.stalled_updates} stalled · ${c.missing_updates} missing · valid-output rate ${c.valid_output_rate==null?'—':(100*c.valid_output_rate).toFixed(0)+'%'} · request p95 ${c.latency_p95_seconds==null?'—':c.latency_p95_seconds.toFixed(1)+'s'}`;
  for(const agent of ['A','B']){const record=activity.agents[agent];if(record.state==='generating'||record.state==='queued'){const elapsed=(now-Date.parse(record.state_since))/1000;const limit=record.request_deadline_seconds??config.request_timeout_seconds??Math.min(config.minute_seconds||60,config.timeout_seconds||180);$('live-state-'+agent).textContent=!verified?'Recorded pending request · worker unverified':record.state==='queued'?labels.queued:elapsed>limit?`Request overdue · ${duration(elapsed)} since start · inspect violations`:`Generating · waiting for model response · ${duration(elapsed)} elapsed`;}}
 }
 setInterval(tick,1000);
 return {render};
})();
